#!/usr/bin/env python3
"""ps2_keymap.py -- the PS/2 set-2 -> Linux key code table the Moonlight client needs (interface
0.6: the core hands a program Main's keys as the PS/2 set-2 codes hps_io delivers). Generated as
the INVERSE of Main_MiSTer's own table (input.cpp `ev2ps2[]`, Linux key code -> set 2), so a key
reaches the host as the same Linux key code Main read; upstream moonlight-embedded's keyCodes[]
then gives the host's key code.

    ps2_keymap.py MAIN_MISTER_DIR > clients/moonlight/src/mister/ps2_keys.h

Where two Linux codes share a set-2 code the lower (the standard key) wins. Pause is special:
Main sends E1 14 77 E1 F0 14 F0 77, which hps_io delivers as one event, extended 0x77; so is
PrintScreen (E0 12 E0 7C / E0 F0 7C E0 F0 12 -> extended 0x7C, pressed / released).
"""
import os
import re
import sys

EXT = 0x080000


def main(argv):
    if len(argv) != 2:
        print(__doc__, file=sys.stderr)
        return 2
    src = open(os.path.join(argv[1], "input.cpp")).read()
    body = src[src.index("static const int ev2ps2[]"):]
    body = body[body.index("{") + 1:body.index("};")]
    table = {}
    flags = {"NONE": 0xFF, "EXT": EXT, "LCTRL": 0x100, "LSHIFT": 0x200, "LALT": 0x400, "LGUI": 0x800,
             "RCTRL": 0x1000, "RSHIFT": 0x2000, "RALT": 0x4000, "RGUI": 0x8000,
             "EMU_SWITCH_1": 0x100000, "EMU_SWITCH_2": 0x200000, "UPSTROKE": 0x400000}
    for m in re.finditer(r"^\s*([^,/\n]+?)\s*,?\s*//\s*(\d+)", body, re.M):
        expr, code = m.group(1), int(m.group(2))
        v = 0
        for term in expr.split("|"):
            term = term.strip()
            v |= flags[term] if term in flags else int(term, 0)
        if v == 0xFF or (v & 0xFF) in (0x00, 0xFF):
            continue
        ps2 = v & 0xFF
        if ps2 == 0xE1:                       # KEY_PAUSE: hps_io's extended 0x77
            key = (1, 0x77)
        elif ps2 == 0xE2:                     # KEY_SYSRQ (PrintScreen): E0 12 E0 7C -> extended 0x7C
            key = (1, 0x7C)
        else:
            key = (1 if v & EXT else 0, ps2)
        table.setdefault(key, code)
    out = ["/* clients/moonlight/src/mister/ps2_keys.h -- PS/2 set 2 (+E0) -> Linux key code: the",
           " * inverse of Main_MiSTer's input.cpp ev2ps2[] (generated by tools/ps2_keymap.py; do not",
           " * edit). ps2_linux[ext][code]; 0 = no key. GPL-3.0-or-later (clients/). */",
           "#ifndef MISTER_PS2_KEYS_H", "#define MISTER_PS2_KEYS_H", "",
           "static const unsigned short ps2_linux[2][256] = {"]
    for ext in (0, 1):
        out.append("  {")
        for base in range(0, 256, 8):
            out.append("    " + " ".join("%3d," % table.get((ext, c), 0) for c in range(base, base + 8)))
        out.append("  },")
    out += ["};", "", "#endif", ""]
    sys.stdout.write("\n".join(out))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
